const cfg = $('Set Configuration Fields').first().json;
return [{ json: { ticket_text: cfg.testTicketText, subject: 'Shop floor screen shows stale orders',
  customer_email: 'test@example.com', ticket_id: 'manual-test' } }];

// Single entry point for BOTH the webhook path and the manual/sheet path, so
// every downstream node can safely back-reference $('Normalize Ticket Data')
// regardless of which trigger fired.
const j = $json;
const body = j.body ?? j;

const ticket_text = String(
  body.text ?? body.message ?? body.description ?? body.ticket_text ?? j.ticket_text ?? ''
).trim();

if (!ticket_text) {
  throw new Error('No ticket text found. Expected one of: text, message, description, ticket_text.');
}

return [{ json: {
  ticket_id: body.id ?? body.ticket_id ?? j.ticket_id ?? `local-${Date.now()}`,
  customer_email: body.email ?? body.from ?? j.customer_email ?? '',
  subject: body.subject ?? j.subject ?? '',
  ticket_text,
  received_at: new Date().toISOString().slice(0, 19).replace('T', ' '),
} }];

const r = $json.output ?? $json;
const src = $('Normalize Ticket Data').first().json;
return [{ json: {
  ...src,
  category: r.category ?? '',
  severity: r.severity ?? 'needs_info',
  sentiment: r.sentiment ?? 'neutral',
  is_question_vs_bug: r.is_question_vs_bug ?? 'unclear',
  contains_credentials: !!r.contains_credentials,
  one_line_summary: r.one_line_summary ?? '',
  missing_info: (r.missing_info || []).join(' | '),
  customer_language: r.customer_language || 'the same language as the ticket',
} }];

// A ticket containing what looks like a credential never reaches the drafting
// agent — the text is not echoed back into another model call, and the reply
// is a fixed template rather than generated. This is the one path in the
// workflow where NOT using AI is the correct engineering choice.
const t = $json;
return [{ json: {
  ...t,
  final_route: 'SECURITY_HOLD',
  draft_reply: 'Thanks for getting in touch. It looks like your message may contain a password or access key. For your security, please rotate that credential now, and reply without including it — a member of the team will pick this up from there.',
  confidence_in_draft: 'n/a',
  confidence_reason: 'Fixed template — credential detected, ticket text deliberately not sent to a model for drafting.',
  internal_note_for_agent: 'Ticket flagged as containing credentials. Original text withheld from the drafting agent. Verify rotation before closing.',
} }];

const r = $json.output ?? $json;
const t = $('Process Triage Results').first().json;

const parts = [];
if (r.found_answer) {
  parts.push('DOCS COVER THIS.');
} else {
  parts.push('DOCS DO NOT COVER THIS — do not invent a fix.');
  if (r.docs_gap) parts.push(`Gap: ${r.docs_gap}`);
}
if (r.key_facts && r.key_facts.length) {
  parts.push('Facts from docs:');
  r.key_facts.forEach(f => parts.push(`- ${f}`));
}
if (r.suggested_resolution) parts.push(`Suggested resolution: ${r.suggested_resolution}`);
if (r.inferred_notes) parts.push(`INFERRED (not from docs, treat carefully): ${r.inferred_notes}`);

return [{ json: {
  ...t,
  found_answer: !!r.found_answer,
  relevant_doc_urls: (r.relevant_doc_urls || []).join(' | '),
  docs_gap: r.docs_gap ?? '',
  research_summary: parts.join('\n'),
} }];

options.systemMessage:
=You draft a support reply. Everything factual has already been researched — your job is wording, not investigation.

WHAT RESEARCH FOUND:
{{ $('Format Research Findings').first().json.research_summary }}

CUSTOMER SENTIMENT: {{ $('Process Triage Results').first().json.sentiment }}
SEVERITY: {{ $('Process Triage Results').first().json.severity }}
REPLY IN THIS LANGUAGE: {{ $('Process Triage Results').first().json.customer_language }}

TONE GUIDE:
{{ $('Set Configuration Fields').first().json.toneGuide }}

RULES:
- Never state a fact that is not in the research above. If research found no answer, the draft should honestly say the team is looking into it — not invent a fix.
- An angry customer gets a calmer, shorter reply, not a more apologetic one. Acknowledge the problem once, then get to substance.
- Never promise a timeline, refund, or feature. Those are decisions a human makes.
- `confidence_in_draft` is your honest read on whether this should go out without human review. Low confidence is a legitimate and useful answer.

