const d = $json.output ?? $json;
const ctx = $('Format Research Findings').first().json;
return [{ json: { ...ctx,
  draft_reply: d.draft_reply ?? '',
  confidence_in_draft: d.confidence_in_draft ?? 'low',
  confidence_reason: d.confidence_reason ?? '',
  internal_note_for_agent: d.internal_note_for_agent ?? '',
  suggested_tags: (d.suggested_tags || []).join(' | '),
} }];

const t = $json;
const resumeUrl = $execution.resumeUrl;
const send = `${resumeUrl}?decision=SEND`;
const rewrite = `${resumeUrl}?decision=REWRITE`;
const escalate = `${resumeUrl}?decision=ESCALATE`;

const lines = [
  `🎫 Ticket needs review — ${t.severity.toUpperCase()} / ${t.sentiment}`,
  t.subject ? `Subject: ${t.subject}` : '',
  `Summary: ${t.one_line_summary}`,
  `Draft confidence: ${t.confidence_in_draft} — ${t.confidence_reason}`,
  t.docs_gap ? `⚠️ Docs gap: ${t.docs_gap}` : '',
  '',
  '--- DRAFT ---',
  t.draft_reply,
  '--- END DRAFT ---',
  '',
  `✅ Send as-is → ${send}`,
  `✏️ I'll rewrite it → ${rewrite}`,
  `🚨 Escalate to engineering → ${escalate}`,
];
return [{ json: { ...t, review_text: lines.filter(Boolean).join('\n') } }];

// Rebuild from the escalation node rather than trusting the resume payload's
// shape — the safest option for the one boundary that cannot be verified
// without a live run. If clicking a link does not route correctly, this is
// the first node to inspect: n8n may deliver query params under $json.query
// OR $json.body depending on version, so both are checked.
const t = $('Prepare Escalation Request').first().json;
const raw = ($json.query && $json.query.decision) || ($json.body && $json.body.decision) || 'REWRITE';
const decision = String(raw).toUpperCase();
const valid = ['SEND', 'REWRITE', 'ESCALATE'];
return [{ json: {
  ...t,
  human_decision: valid.includes(decision) ? decision : 'REWRITE',
  final_route: valid.includes(decision) ? `HUMAN_${decision}` : 'HUMAN_REWRITE',
} }];

// Every ticket the docs failed to answer becomes a documentation to-do.
// Cheapest possible source of "what should we write next" — it is a byproduct
// of work already done, not a separate research effort.
const t = $json;
return [{ json: {
  text: `📝 Docs gap found — ${t.category || 'uncategorised'}\n${t.one_line_summary}\n${t.docs_gap || 'No doc page covered this.'}`,
} }];
